using System;
using System.Collections.Generic;
using System.Drawing;
using System.Drawing.Imaging;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Windows.Forms;
using ShareMeRowell;

class StudioChecks {
    static void Require(bool value,string message){if(!value)throw new Exception(message);}
    static IEnumerable<Control> All(Control root){foreach(Control c in root.Controls){yield return c;foreach(var child in All(c))yield return child;}}
    static void Click(Form form,string text){All(form).OfType<SoftButton>().Single(b=>b.Text==text).PerformClick();Application.DoEvents();}
    static Bitmap Render(HeroProfile profile,int level=1,int gear=1){var image=new Bitmap(192,192);using(var g=Graphics.FromImage(image)){g.Clear(Color.Transparent);PortraitCatalog.Draw(g,profile,level,gear,0,0,new Rectangle(0,0,192,192));}return image;}
    static long Difference(Bitmap a,Bitmap b){long n=0;for(int y=0;y<a.Height;y++)for(int x=0;x<a.Width;x++)if(a.GetPixel(x,y)!=b.GetPixel(x,y))n++;return n;}
    static Rectangle OnForm(Form form,Control control){return new Rectangle(form.PointToClient(control.PointToScreen(Point.Empty)),control.Size);}
    static void Snapshot(Form form,string path){Application.DoEvents();using(var image=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(image,new Rectangle(0,0,form.Width,form.Height));image.Save(path,ImageFormat.Png);}}
    static object Field(object value,string name){return value.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(value);}
    [STAThread] static int Main(string[] args){try{
        string folder=Path.GetFullPath(args[0]);Directory.CreateDirectory(folder);Application.EnableVisualStyles();var passed=new List<string>();
        Require(PortraitCatalog.HasAuthoredPortrait(0,0)&&PortraitCatalog.HasAuthoredPortrait(0,1),"A default whole-character look is missing");
        foreach(int look in new[]{0,1})foreach(int hair in Enumerable.Range(0,6))foreach(int expression in Enumerable.Range(0,4))using(var image=Render(new HeroProfile{Look=look,Hair=hair,Eyes=expression,HairColour=5})){int opaque=0;for(int y=0;y<192;y++)for(int x=0;x<192;x++)if(image.GetPixel(x,y).A>128)opaque++;Require(opaque>4000,"A default appearance cel is incomplete");}passed.Add("Both default looks contain six complete hairstyles and four expressions without separate head/body artwork");
        var baseProfile=new HeroProfile{HairColour=5};using(var baseline=Render(baseProfile)){
            var variations=new List<HeroProfile>();var p=baseProfile.Copy();p.Skin=4;variations.Add(p);p=baseProfile.Copy();p.HairColour=2;variations.Add(p);p=baseProfile.Copy();p.Shirt=2;variations.Add(p);p=baseProfile.Copy();p.Element=1;variations.Add(p);p=baseProfile.Copy();p.Eyes=2;variations.Add(p);
            foreach(var variant in variations)using(var image=Render(variant))Require(Difference(baseline,image)>120,"An appearance control had no visible effect");
        }
        foreach(int look in new[]{0,1})using(var first=Render(new HeroProfile{Look=look,HairColour=5}))using(var deep=Render(new HeroProfile{Look=look,HairColour=5,Skin=4})){foreach(var zone in new[]{new Rectangle(44,110,42,40),new Rectangle(106,110,44,40)}){int changed=0;for(int y=zone.Top;y<zone.Bottom;y++)for(int x=zone.Left;x<zone.Right;x++)if(first.GetPixel(x,y)!=deep.GetPixel(x,y))changed++;Require(changed>15,"Skin tone did not reach both hands");}}
        passed.Add("Skin, hair, outfit, accent and expression choices independently change the complete default portrait, including both hands");
        foreach(int role in Enumerable.Range(0,Adventure.Roles.Length).Where(Adventure.IsFixedDesign)){
            Require(PortraitCatalog.HasAuthoredPortrait(role),"A complete fixed portrait is missing");var a=new HeroProfile{Role=role};var b=new HeroProfile{Role=role,Look=1,Hair=5,Skin=4,HairColour=4,Shirt=4,Eyes=3,Element=5};using(var first=Render(a,100,100))using(var alternate=Render(b,100,100))Require(Difference(first,alternate)==0,"Personal style changed a complete signature");
        }passed.Add("All eighteen fixed characters, including Seraph and Sovereign, ignore personal style fields");
        foreach(int role in new[]{5,6})using(var first=Render(new HeroProfile{Role=role},100,Adventure.RoleLevels[role]))using(var last=Render(new HeroProfile{Role=role},100,Adventure.MasteryLevel(role)))Require(Difference(first,last)>1000,"Fantasy mastery reused its starter art");passed.Add("Heavenly and Sovereign starter/mastery outfits use separate complete authored artwork");
        string state=Path.Combine(folder,"isolated-profile");using(var store=new JourneyStore(state))using(var form=new AdventurerForm(store,()=>{})){
            form.ShowInTaskbar=false;form.StartPosition=FormStartPosition.Manual;form.Location=new Point(-20000,-20000);form.Show();Application.DoEvents();
            var search=All(form).OfType<TextBox>().Single(c=>c.AccessibleName=="Search characters");var filter=All(form).OfType<ComboBox>().Single(c=>c.AccessibleName=="Filter characters");search.Text="madara";Application.DoEvents();var visible=All(form).OfType<CharacterTile>().Where(c=>c.Visible).ToArray();Require(visible.Length==1&&visible[0].RoleIndex==23,"Search did not isolate Madara");visible[0].PerformClick();Application.DoEvents();Require(store.Profile.Role==0&&store.Xp==0,"Locked preview changed progress or equipment");var equip=All(form).OfType<SoftButton>().Single(c=>c.AccessibleName=="Equip previewed character");Require(!equip.Enabled,"A locked character could be equipped");Snapshot(form,Path.Combine(folder,"studio-locked-preview.png"));passed.Add("Search selects a locked full-colour preview without equipping it or changing XP");
            search.Text="";filter.SelectedIndex=3;Application.DoEvents();Require(All(form).OfType<CharacterTile>().Where(c=>c.Visible).All(c=>!Adventure.IsFixedDesign(c.RoleIndex)),"Customizable filter included fixed designs");filter.SelectedIndex=0;Application.DoEvents();var scroll=All(form).OfType<StudioScroll>().Single(c=>c.Content.Controls.OfType<CharacterTile>().Any());Require(scroll.MaximumOffset>0,"Collection was not scrollable");scroll.ScrollTo(0);typeof(Control).GetMethod("OnMouseWheel",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(scroll,new object[]{new HandledMouseEventArgs(MouseButtons.None,0,0,0,-120)});Require(scroll.ScrollOffset>0,"Wheel did not scroll the collection");scroll.ScrollTo(int.MaxValue);Require(scroll.ScrollOffset==scroll.MaximumOffset&&scroll.Content.Top==-scroll.MaximumOffset,"Scroll did not clamp to content bounds");
            var rail=All(scroll).Single(c=>c.AccessibleRole==AccessibleRole.ScrollBar);typeof(Control).GetMethod("OnKeyDown",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(rail,new object[]{new KeyEventArgs(Keys.Home)});Require(scroll.ScrollOffset==0,"Home did not scroll to the top");var flags=BindingFlags.Instance|BindingFlags.NonPublic;rail.GetType().GetMethod("OnMouseDown",flags).Invoke(rail,new object[]{new MouseEventArgs(MouseButtons.Left,1,rail.Width/2,8,0)});rail.GetType().GetMethod("OnMouseMove",flags).Invoke(rail,new object[]{new MouseEventArgs(MouseButtons.Left,0,rail.Width/2,60,0)});rail.GetType().GetMethod("OnMouseUp",flags).Invoke(rail,new object[]{new MouseEventArgs(MouseButtons.Left,1,rail.Width/2,60,0)});Require(scroll.ScrollOffset>0,"Dragging the thumb did not scroll");passed.Add("Collection filters and custom scrollbar wheel, keyboard, drag and limits work without native white scrollbars");
            Click(form,"Style");All(form).OfType<TextBox>().Single(c=>c.AccessibleName=="Nearby name").Text="Studio courier";foreach(string choice in new[]{"Look: Girl","Hair: Long","Hair colour: Silver","Skin tone: Deep","Outfit colour: Violet","Element colour: Fire","Expression: Focused"})All(form).OfType<StyleOption>().Single(c=>c.AccessibleName==choice).PerformClick();Application.DoEvents();Require(store.Profile.Look==1&&store.Profile.Hair==3&&store.Profile.Skin==4&&store.Profile.Shirt==1&&store.Profile.Element==1&&store.Profile.Eyes==3,"A visible style control did not autosave");Snapshot(form,Path.Combine(folder,"studio-personal-style.png"));
            foreach(var size in new[]{new Size(1136,779),form.MinimumSize}){((Form)form).Size=size;Application.DoEvents();var done=All(form).OfType<SoftButton>().Single(c=>c.Text=="Done");Require(form.ClientRectangle.Contains(OnForm(form,done)),"Done button was clipped at a supported size");var stage=(Control)Field(form,"hero");Require(stage.Width>150&&stage.Height>150&&form.ClientRectangle.Contains(OnForm(form,stage)),"Character preview was clipped or collapsed");var bar=(Control)Field(form,"xpBar");Require(bar.Height<=8,"XP bar expanded into a block");}passed.Add("Preview, footer, Done and slim XP bar stay inside the default and minimum window sizes");
            form.Close();
        }
        using(var store=new JourneyStore(state)){Require(store.Profile.Name=="Studio courier"&&store.Profile.Look==1&&store.Profile.Hair==3&&store.Profile.Skin==4&&store.Profile.Shirt==1&&store.Xp==0,"Appearance or progress changed after restart");}passed.Add("Whole-avatar appearance changes persist after closing and restarting without XP changes");
        foreach(var size in new[]{new Size(1136,779),new Size(1000,680)}){
            string capture=Path.Combine(folder,"main-"+size.Width+"x"+size.Height);Directory.CreateDirectory(capture);using(var form=new MainForm(capture)){form.ShowInTaskbar=false;form.StartPosition=FormStartPosition.Manual;form.Location=new Point(-20000,-20000);form.Show();((Form)form).Size=size;Application.DoEvents();All(form).OfType<SoftButton>().Single(b=>b.Text=="Receive files").PerformClick();Application.DoEvents();var qr=(PictureBox)Field(form,"qr");Require(qr.Image!=null,"Receive QR was missing");Snapshot(form,Path.Combine(capture,"receive.png"));var server=(TransferServer)Field(form,"server");File.WriteAllText(Path.Combine(capture,"pairing.txt"),server.Pairing(new[]{"127.0.0.1"}));server.Name=new string('界',24);All(form).OfType<SoftButton>().Single(b=>b.Text=="Advanced network options").PerformClick();Application.DoEvents();Snapshot(form,Path.Combine(capture,"receive-expanded.png"));File.WriteAllText(Path.Combine(capture,"pairing-expanded.txt"),server.Pairing(new[]{"127.0.0.1"}));form.Close();}
        }passed.Add("Receive QR snapshots cover default/minimum sizes, expanded networks and maximum-length Unicode names");
        File.WriteAllText(Path.Combine(folder,"result.json"),Wire.Encode(new{passed=passed.Count,checks=passed,realInstallationUsed=false,phoneUsed=false}));Console.WriteLine(string.Join(Environment.NewLine,passed));return 0;
    }catch(Exception error){Console.Error.WriteLine(error);return 1;}}
}
